import { useState } from "react";
import { Collapsible, CollapsibleTrigger, CollapsibleContent } from "@nativecn/ui/components/collapsible";
import { Button } from "@nativecn/ui/components/button";

export default function App() {
  const [open, setOpen] = useState(false);
  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <CollapsibleTrigger asChild>
        <Button variant="ghost" onPress={() => setOpen(!open)}>Toggle</Button>
      </CollapsibleTrigger>
      <CollapsibleContent>
        <Text>Hidden content revealed on expand.</Text>
      </CollapsibleContent>
    </Collapsible>
  );
}
